#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_gradientMode;
uniform float amzp_gradAngle;
uniform float amzp_gradCenterX;
uniform float amzp_gradCenterY;
uniform float amzp_gradScale;
uniform float amzp_gradSoftness;
uniform float amzp_gradOffset;
uniform float amzp_gradInvert;
uniform float amzp_gradAspect;
uniform float amzp_brightExposure;
uniform float amzp_brightContrast;
uniform float amzp_brightSaturation;
uniform float amzp_brightGamma;
uniform float amzp_brightHighlights;
uniform float amzp_brightShadows;
layout(color) uniform half4 amzp_brightTint;
uniform float amzp_brightTintStr;
uniform float amzp_brightTemp;
uniform float amzp_darkExposure;
uniform float amzp_darkContrast;
uniform float amzp_darkSaturation;
uniform float amzp_darkGamma;
uniform float amzp_darkHighlights;
uniform float amzp_darkShadows;
layout(color) uniform half4 amzp_darkTint;
uniform float amzp_darkTintStr;
uniform float amzp_darkTemp;
uniform float amzp_masterExposure;
uniform float amzp_masterContrast;
uniform float amzp_masterSaturation;
uniform float amzp_viewGradient;
uniform float amzp_globalMix;
    float lum(float3 c) {
        return dot(c, float3(0.2126, 0.7152, 0.0722));
    }
    float getGradient(float2 uv) {
        float gm = float(int(amzp_gradientMode));
        float2 center = float2(amzp_gradCenterX, amzp_gradCenterY);
        float2 p = uv - center;
        p.x *= amzp_gradAspect;
        float g = 0.0;
        if (gm < 1.5) {
            float ang = amzp_gradAngle * 3.14159265359 / 180.0;
            float2 dir = float2(cos(ang), sin(ang));
            g = dot(p, dir) / max(amzp_gradScale, 0.00001) + 0.5;
        } else if (gm < 2.5) {
            float dist = length(p);
            g = dist / max(amzp_gradScale * 0.5, 0.00001);
        } else if (gm < 3.5) {
            float dist = length(p);
            float ang = amzp_gradAngle * 3.14159265359 / 180.0;
            float cs = cos(ang);
            float sn = sin(ang);
            float2 rp = float2(p.x * cs + p.y * sn, -p.x * sn + p.y * cs);
            rp.y *= 0.6;
            dist = length(rp);
            g = dist / max(amzp_gradScale * 0.5, 0.00001);
        } else if (gm < 4.5) {
            float ang = amzp_gradAngle * 3.14159265359 / 180.0;
            float cs = cos(ang);
            float sn = sin(ang);
            float2 rp = float2(p.x * cs + p.y * sn, -p.x * sn + p.y * cs);
            float dist = abs(rp.x) + abs(rp.y);
            g = dist / max(amzp_gradScale * 0.5, 0.00001);
        } else {
            float ang = atan(p.y, p.x + 0.00001);
            float targetAng = amzp_gradAngle * 3.14159265359 / 180.0;
            float diff = ang - targetAng;
            diff = mod(diff + 3.14159265359, 2.0 * 3.14159265359) - 3.14159265359;
            g = abs(diff) / 3.14159265359;
        }
        g += amzp_gradOffset;
        float soft = max(amzp_gradSoftness, 0.01);
        g = smoothstep(0.5 - soft, 0.5 + soft, g);
        if ((amzp_gradInvert>0.5)) {
            g = 1.0 - g;
        }
        return clamp(g, 0.0, 1.0);
    }
    float3 gradeZone(float3 rgb, float exposure, float contrast, float saturation,
                   float gamma, float highlights, float shadows,
                   float3 tintCol, float tintStr, float temp) {
        float3 result = rgb;
        if (abs(exposure) > 0.00001) {
            result *= pow(2.0, exposure);
        }
        if (abs(contrast) > 0.5) {
            float c = contrast / 100.0;
            float factor = 1.0 + c;
            result = (result - 0.18) * factor + 0.18;
            if (c > 0.0) {
                float s = c * 0.3;
                result = result + s * (result - 0.5) * (1.0 - abs(result - 0.5) * 2.0);
            }
        }
        if (abs(highlights) > 0.5 || abs(shadows) > 0.5) {
            float l = lum(result);
            float hlMask = smoothstep(0.5, 1.0, l);
            hlMask *= hlMask;
            float shMask = 1.0 - smoothstep(0.0, 0.5, l);
            shMask *= shMask;
            float hlAdj = highlights / 100.0 * 0.4;
            float shAdj = shadows / 100.0 * 0.4;
            float origLum = max(l, 0.00001);
            float newLum = l + hlAdj * hlMask + shAdj * shMask;
            result *= max(newLum, 0.0) / origLum;
        }
        if (abs(gamma - 1.0) > 0.00001) {
            result = pow(max(result, 0.0), float3(1.0 / max(gamma, 0.00001)));
        }
        if (abs(saturation) > 0.5) {
            float s = 1.0 + saturation / 100.0;
            float l = lum(result);
            result = mix(float3(l), result, s);
        }
        if (abs(temp) > 0.5) {
            float t = temp / 100.0 * 0.08;
            result.r += t;
            result.b -= t;
            result.g += t * 0.15;
        }
        if (tintStr > 0.00001) {
            result = mix(result, result * tintCol, tintStr);
        }
        return result;
    }
    void amzRender() {
        float2 uv = amzScreenNorm();
        float4 original = amzTexture(0, uv);
        float3 rgb = max(original.rgb, 0.0);
        float3 baseRGB = rgb;
        float grad = getGradient(uv);
        if ((amzp_viewGradient>0.5)) {
            amzOutput = float4(float3(grad), 1.0);
            return;
        }
        float3 brightGraded = gradeZone(rgb,
            amzp_brightExposure, amzp_brightContrast, amzp_brightSaturation,
            amzp_brightGamma, amzp_brightHighlights, amzp_brightShadows,
            amzp_brightTint.rgb, amzp_brightTintStr, amzp_brightTemp);
        float3 darkGraded = gradeZone(rgb,
            amzp_darkExposure, amzp_darkContrast, amzp_darkSaturation,
            amzp_darkGamma, amzp_darkHighlights, amzp_darkShadows,
            amzp_darkTint.rgb, amzp_darkTintStr, amzp_darkTemp);
        float3 result = mix(darkGraded, brightGraded, grad);
        if (abs(amzp_masterExposure) > 0.00001) {
            result *= pow(2.0, amzp_masterExposure);
        }
        if (abs(amzp_masterContrast) > 0.5) {
            float mc = amzp_masterContrast / 100.0;
            result = (result - 0.18) * (1.0 + mc) + 0.18;
        }
        if (abs(amzp_masterSaturation - 100.0) > 0.5) {
            float ms = amzp_masterSaturation / 100.0;
            float l = lum(result);
            result = mix(float3(l), result, ms);
        }
        result = mix(baseRGB, result, amzp_globalMix);
        result = clamp(result, 0.0, 1.0);
        amzOutput = float4(result, original.a);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

